examples:
```tsx
// Ghost Button - transparent with hover background
import { ArrowRight } from 'lucide-react';
<Button variant="ghost" Icon={ArrowRight} iconPosition="right">Next Step</Button>
```

```tsx
// Button with Icon in Loading State - spinner replaces icon, text updates
import { Trash2 } from 'lucide-react';
<Button variant="danger" Icon={Trash2} loading={isDeleting}>
  {isDeleting ? 'Deleting...' : 'Delete'}
</Button>
```

```tsx
// Icon Only Button (requires aria-label or accessible text child)
import { Search } from 'lucide-react';
<Button variant="primary" iconOnly={true} Icon={Search} aria-label="Search" />
```
